<template><div class="office-page" v-loading="loading"><header class="office-toolbar"><h2>{{ identity.isManager?'项目汇报与反馈':'工作汇报' }}</h2><div class="office-actions"><el-button circle title="刷新汇报" @click="load"><span class="material-symbols-outlined">refresh</span></el-button><el-button type="primary" @click="open">提交汇报</el-button></div></header>
  <div class="office-toolbar report-filters"><el-select v-model="project" clearable placeholder="所有参与项目" aria-label="筛选汇报项目" @change="loadReports"><el-option v-for="p in projects" :key="p.projectId" :label="p.name" :value="p.projectId"/></el-select><el-radio-group v-model="filter"><el-radio-button value="all">全部</el-radio-button><el-radio-button value="mine">我的</el-radio-button><el-radio-button value="submitted">待阅</el-radio-button><el-radio-button value="reviewed">已阅</el-radio-button></el-radio-group></div>
  <el-empty v-if="!filtered.length" description="暂无工作汇报"><el-button @click="open">提交第一份汇报</el-button></el-empty>
  <div class="report-list"><article v-for="r in filtered" :key="r.id" class="report"><header class="office-toolbar"><div><h3>{{ r.title }}</h3><small class="office-muted">{{ r.authorName }} · {{ r.projectName }} · {{ date(r.createdAt) }}</small></div><el-tag :type="r.status==='reviewed'?'success':'warning'">{{ r.status==='reviewed'?'已阅':'待阅' }}</el-tag></header><p class="report-body">{{ r.content }}</p><el-button v-if="r.canReview&&r.status==='submitted'" @click="review(r)">标记已阅</el-button><div class="report-replies"><div v-for="reply in r.replies" :key="reply.id"><small class="office-muted">{{ reply.authorName }} · {{ date(reply.createdAt) }}</small><p>{{ reply.content }}</p></div></div><form class="reply-form" @submit.prevent="reply(r)"><el-input v-model="drafts[r.id]" :aria-label="`回复 ${r.title}`" placeholder="回复汇报" maxlength="2000"/><el-button native-type="submit" :disabled="!drafts[r.id]?.trim()" :loading="sending===r.id">回复</el-button></form></article></div>
  <el-dialog v-model="visible" title="提交工作汇报" width="min(600px, calc(100vw - 24px))"><form class="office-form" @submit.prevent="submit"><label>项目<el-select v-model="form.projectId" aria-label="汇报项目"><el-option v-for="p in projects.filter(p=>p.status===1)" :key="p.projectId" :label="p.name" :value="p.projectId"/></el-select></label><label>标题<el-input v-model="form.title" maxlength="150"/></label><label>进展、问题与下一步<el-input v-model="form.content" type="textarea" :rows="6" maxlength="5000" show-word-limit/></label><el-button type="primary" native-type="submit" :loading="saving">提交</el-button></form></el-dialog>
</div></template>
<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue'
import {ElMessage} from 'element-plus'
import {useIdentityStore} from '@/stores/identity'
import {useWorkspaceStore} from '@/stores/workspace'
import request from '@/utils/request'
const identity=useIdentityStore(),workspace=useWorkspaceStore(),projects=ref<any[]>([]),reports=ref<any[]>([]),project=ref(''),filter=ref('all'),loading=ref(false),saving=ref(false),visible=ref(false),sending=ref<number|null>(null),drafts=reactive<Record<string,string>>({}),form=reactive({projectId:'',title:'',content:''})
const filtered=computed(()=>reports.value.filter(r=>filter.value==='all'||filter.value==='mine'&&String(r.authorId)===String(identity.user?.userId)||r.status===filter.value))
function date(v:string){return String(v||'').replace('T',' ').slice(0,16)}
async function loadReports(){const r:any=await request.get('/task/reports',{params:{projectId:project.value||undefined}});reports.value=r.data}
async function load(){loading.value=true;try{const p:any=await request.get('/task/project/list',{params:{spaceId:workspace.spaceId}});projects.value=p.data;await loadReports()}finally{loading.value=false}}
function open(){Object.assign(form,{projectId:project.value||projects.value.find(p=>p.status===1)?.projectId||'',title:'',content:''});visible.value=true}
async function submit(){if(!form.projectId||!form.title.trim()||!form.content.trim()){ElMessage.warning('请填写项目、标题和内容');return}saving.value=true;try{await request.post('/task/reports',form);visible.value=false;await loadReports();ElMessage.success('汇报已提交')}finally{saving.value=false}}
async function reply(r:any){sending.value=r.id;try{await request.post(`/task/reports/${r.id}/replies`,{content:drafts[r.id]});drafts[r.id]='';await loadReports()}finally{sending.value=null}}
async function review(r:any){await request.put(`/task/reports/${r.id}/review`);await loadReports();ElMessage.success('已标记已阅')}
onMounted(load)
</script>
<style scoped>
.report-filters{flex-wrap:wrap;gap:12px;margin:var(--space-5) 0}.report-filters .el-select{width:220px;max-width:100%}.report-list{display:grid;gap:var(--space-5)}.report{border:1px solid var(--c-border);padding:var(--space-5);border-radius:var(--radius-md);min-width:0}.report h3{margin:0 0 8px;font-size:var(--text-section);overflow-wrap:anywhere}.report-body,.report-replies p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7}.report-replies{border-left:2px solid var(--c-border);padding-left:var(--space-4);margin:var(--space-4) 0}.report-replies>div+div{margin-top:16px}.reply-form{display:flex;gap:8px}.report header{align-items:flex-start;gap:12px}.report header>div{min-width:0}@media(max-width:600px){.report{padding:12px}.report-filters{display:block}.report-filters .el-radio-group{margin-top:12px}.report header{flex-wrap:wrap}}
</style>
